def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime factors with multiplicity
    def prime_factors_with_multiplicity(n):
        factors = []
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    factors = prime_factors_with_multiplicity(a)

    # Check if there are exactly 3 prime factors (with multiplicity)
    if len(factors) == 3:
        return all(is_prime(f) for f in factors)
    else:
        return False
